// payment.bynk
context payment

exports transparent { Amount }

// money.bynk
commons money

type Amount = Int where NonNegative

// orders.bynk
context orders

uses money
consumes payment                           // ✗ `Amount` is also in scope from `money`
consumes payment { Amount as PayAmount }   // ✓ `PayAmount` is `payment`'s
